<script setup lang="ts">import type{RoutePerformanceItem}from '@/types/dashboard';defineProps<{items:RoutePerformanceItem[];loading:boolean}>();const emit=defineEmits<{detail:[id:number]}>();const money=(v:number)=>new Intl.NumberFormat('vi-VN',{notation:'compact',maximumFractionDigits:1}).format(v)</script>
<template><v-card class="pa-4 pa-md-5 h-100" border rounded="xl"><div class="d-flex justify-space-between mb-4"><div><div class="text-h6 font-weight-bold">Tỷ lệ thu theo tuyến</div><div class="text-caption text-medium-emphasis">Tuyến tỷ lệ thấp được ưu tiên phía trên</div></div><v-icon icon="mdi-routes" color="primary" /></div><v-skeleton-loader v-if="loading" type="list-item-three-line@4" /><div v-else-if="!items.length" class="empty-state">Chưa có dữ liệu tuyến</div><div v-else class="route-list"><div v-for="item in items.slice(0,7)" :key="item.route_id" class="route-item"><div class="d-flex justify-space-between ga-3"><div class="font-weight-medium text-truncate">{{ item.route_name }}</div><strong :class="item.completion_rate<70?'text-error':item.completion_rate<90?'text-warning':'text-success'">{{ item.completion_rate }}%</strong></div><v-progress-linear :model-value="item.completion_rate" :color="item.completion_rate<70?'error':item.completion_rate<90?'warning':'success'" height="7" rounded class="my-2" /><div class="d-flex justify-space-between text-caption text-medium-emphasis"><span>{{ item.collected_households }}/{{ item.total_households }} hộ · Còn {{ item.uncollected_households }}</span><span>{{ money(item.revenue) }} ₫</span></div><v-btn size="x-small" variant="text" color="primary" class="px-0 mt-1" @click="emit('detail',item.route_id)">Xem chi tiết</v-btn></div></div></v-card></template>
